import { localizeRenderedHtml, uiText, pageFamilyCopy, detailCopy, domainHeroLabels, domainDisplayName } from './locale-contract.mjs';
const rawEsc=(v='')=>String(v).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));
function publicText(v=''){const value=String(v);const internal=/approved (?:catalog|commerce|source|provider)|verified (?:product|vacancy|listing|provider|profile|source)|requires? (?:an? )?(?:approved|verified|live|real) |live (?:price|rate|stock|availability) required|provider data required|provisional until|bind .* before publication|source-backed|production content|connector evidence/i;if(!internal.test(value))return value;if(/price|rate|stock|availability/i.test(value))return 'Current price and availability are shown when available.';return 'Current details are shown when available.';}
const esc=(v='')=>rawEsc(publicText(v));
const attr=v=>esc(v);
const media=(section,i=0)=>section.media?.[i]?.src||'';
const img=(src,alt,cls='')=>src?`<img class="${cls}" src="${attr(src)}" alt="${attr(alt)}" loading="${cls.includes('hero')?'eager':'lazy'}">`:'';
const arrow='→';
function sectionHead(kicker,title,link=''){return `<div class="section-heading"><span class="kicker">${esc(kicker||'')}</span>${title?`<h2>${esc(title)}</h2>`:''}${link?`<a class="text-link" href="#contact">${esc(link)} ${arrow}</a>`:''}</div>`}
function applySpatial(html,s){const x=s?.spatial;if(!x||!html.startsWith('<section '))return html;const attrs=`data-spatial-geometry="${attr(x.geometry)}" data-spatial-width="${attr(x.width)}" data-spatial-align="${attr(x.align)}" data-spatial-media="${attr(x.mediaRatio)}" data-spatial-overlap="${x.overlap?'true':'false'}"`;return html.replace('<section ',`<section ${attrs} `);}

function renderHero(v,s,plan){const c=v.content.model.hero||{};const next=v.content.model['next-event'];const hero=media(s);return `<section class="vc-hero template-${attr(s.template)} variant-${attr(s.variant||'hero')}" data-role="${attr(s.role||'OPEN')}" data-layout="${attr(s.layoutMode||'split')}" id="top"><div class="hero-media">${img(hero,'Atmosphere for '+v.content.brand,'hero-image')}<div class="media-vignette"></div></div><div class="hero-grid"><div class="hero-copy"><span class="kicker">${esc(c.eyebrow)}</span><h1>${esc(c.headline)}</h1><p>${esc(c.subheadline)}</p><div class="actions"><a class="button primary" href="#${next?'next-event':'contact'}">${esc(c.primary)} ${arrow}</a><a class="button ghost" href="#contact">${esc(c.secondary)}</a></div></div>${next?`<aside class="next-card"><span class="kicker">${esc(next.kicker)}</span><h3>${esc(next.title)}</h3><div class="event-date">${esc(next.date)}</div><div class="event-time">${esc(next.time)}</div><div class="event-location">⌖ ${esc(next.location)}</div><small>LINEUP</small><strong>${(next.lineup||[]).map(esc).join(' · ')}</strong><a href="#next-event">${esc(next.cta)} ${arrow}</a></aside>`:''}</div></section>`}
function renderNextEvent(s,c){return `<section class="vc-section next-event-feature template-${attr(s.template)} variant-${attr(s.variant||'spotlight')}" data-role="${attr(s.role||'ACTION')}" data-layout="${attr(s.layoutMode||'split')}" id="${attr(s.id)}"><div class="next-event-media">${img(media(s),c.title||'Next event')}</div><div class="next-event-copy"><span class="kicker">${esc(c.kicker)}</span><h2>${esc(c.title)}</h2><div class="big-date">${esc(c.date)}</div><p>${esc(c.time)} · ${esc(c.location)}</p><small>LINEUP</small><strong>${(c.lineup||[]).map(esc).join(' · ')}</strong><a class="button primary" href="#contact">${esc(c.cta||'Get tickets')} ${arrow}</a></div></section>`}
function renderEvents(s,c){const items=c.items||[];return `<section class="vc-section events template-${attr(s.template)} variant-${attr(s.variant||'rail')}" data-role="${attr(s.role||'FRESHNESS')}" data-layout="${attr(s.layoutMode||'rail')}" id="${attr(s.id)}">${sectionHead(c.kicker||'UPCOMING',c.title||'', 'View all')}<div class="event-rail">${items.map((x,i)=>`<article class="event-tile"><div class="event-art">${img(media(s,i),x.title)}</div><div class="event-date-box"><strong>${esc(x.date?.split(' ')[0]||'')}</strong><span>${esc(x.date?.split(' ')[1]||'')}</span></div><div class="event-info"><h3>${esc(x.title)}</h3><span>${esc(x.time||'')}</span><small>${esc(x.meta||'')}</small></div><a class="icon-link" href="#contact" aria-label="Open ${attr(x.title)}">${arrow}</a></article>`).join('')}</div></section>`}
function renderPeople(s,c){return `<section class="vc-section people template-${attr(s.template)} variant-${attr(s.variant||'rail')}" data-role="${attr(s.role||'DISCOVER')}" data-layout="${attr(s.layoutMode||'rail')}" id="${attr(s.id)}">${sectionHead(c.kicker,s.title||'', 'View all')}<div class="people-grid">${(c.items||[]).map((x,i)=>`<article><div class="portrait">${img(media(s,i),x.name)}</div><div class="person-meta"><h3>${esc(x.name)}</h3><span>${esc(x.meta||'')}</span></div></article>`).join('')}</div></section>`}
function renderGallery(s,c){return `<section class="vc-section gallery template-${attr(s.template)} variant-${attr(s.variant||'masonry')}" data-role="${attr(s.role||'MEDIA')}" data-layout="${attr(s.layoutMode||'mosaic')}" id="${attr(s.id)}">${sectionHead(c.kicker,c.title,'View full gallery')}<div class="gallery-mosaic">${(c.items||[]).map((x,i)=>`<figure class="g${i+1}">${img(media(s,i),x.title)}<figcaption>${esc(x.title)}</figcaption></figure>`).join('')}</div></section>`}
function renderFeatures(s,c){return `<section class="vc-section feature-split template-${attr(s.template)} variant-${attr(s.variant||'split')}" data-role="${attr(s.role||'VALUE')}" data-layout="${attr(s.layoutMode||'split')}" id="${attr(s.id)}"><div class="feature-copy">${sectionHead(c.kicker,c.title)}<p class="lead">${esc(c.body||'')}</p><div class="feature-list">${(c.features||c.items||[]).map((x,i)=>{const a=Array.isArray(x)?x:[x.title,x.body];return `<article><span class="feature-icon">${['◌','↯','▣','◇'][i%4]}</span><h3>${esc(a[0])}</h3><p>${esc(a[1]||'')}</p></article>`}).join('')}</div></div><div class="feature-media">${img(media(s),c.title||c.kicker)}</div></section>`}
function renderMetrics(s,c){const items=c.metrics||c.items||[];return `<section class="vc-section metrics template-${attr(s.template)} variant-${attr(s.variant||'metrics')}" data-role="${attr(s.role||'PROOF')}" data-layout="${attr(s.layoutMode||'split')}" id="${attr(s.id)}">${sectionHead(c.kicker,c.title)}<div class="metric-row">${items.map(x=>{const a=Array.isArray(x)?x:[x.title,x.body];return `<article><strong>${esc(a[0])}</strong><span>${esc(a[1]||'')}</span></article>`}).join('')}</div></section>`}
function renderCards(s,c){return `<section class="vc-section card-section template-${attr(s.template)} variant-${attr(s.variant||'cards')}" data-role="${attr(s.role||'VALUE')}" data-layout="${attr(s.layoutMode||'bento')}" id="${attr(s.id)}">${sectionHead(c.kicker,c.title)}${c.body?`<p class="lead">${esc(c.body)}</p>`:''}<div class="pro-card-grid">${(c.items||[]).map((x,i)=>`<article><span class="card-no">0${i+1}</span>${media(s,i)?`<div class="card-media">${img(media(s,i),x.title||x.name||'')}</div>`:''}<h3>${esc(x.title||x.name||'')}</h3>${x.price?`<strong class="price">${esc(x.price)}</strong>`:''}<p>${esc(x.body||x.meta||'')}</p></article>`).join('')}</div></section>`}
function renderSteps(s,c){const steps=c.steps||[];return `<section class="vc-section steps template-${attr(s.template)} variant-${attr(s.variant||'timeline')}" data-role="${attr(s.role||'PROCESS')}" data-layout="${attr(s.layoutMode||'rail')}" id="${attr(s.id)}">${sectionHead(c.kicker,c.title)}<div class="step-grid">${steps.map((x,i)=>{const item=typeof x==='string'?{title:x,body:['Understand the context before choosing the method.','Make the decision legible and low-friction.','Deliver with a clear next state and evidence.'][i]||''}:x;return `<article><span>0${i+1}</span><h3>${esc(item.title||'')}</h3><p>${esc(item.body||'')}</p></article>`}).join('')}</div></section>`}
function renderFaq(s,c){return `<section class="vc-section faq template-${attr(s.template)} variant-${attr(s.variant||'accordion')}" data-role="${attr(s.role||'OBJECTION')}" data-layout="${attr(s.layoutMode||'minimal')}" id="${attr(s.id)}">${sectionHead(c.kicker,c.title||'Questions, answered.')}<div class="faq-list">${(c.items||[]).map((x,i)=>`<details ${i===0?'open':''}><summary>${esc(x[0])}<span>+</span></summary><p>${esc(x[1])}</p></details>`).join('')}</div></section>`}
function renderEditorial(s,c){return `<section class="vc-section editorial-split template-${attr(s.template)} variant-${attr(s.variant||'split')}" data-role="${attr(s.role||'POSITION')}" data-layout="${attr(s.layoutMode||'editorial')}" id="${attr(s.id)}"><div>${sectionHead(c.kicker,c.title)}${c.quote?`<blockquote>“${esc(c.quote)}”</blockquote>`:`<p class="lead">${esc(c.body||'')}</p>`}</div><div class="editorial-media">${img(media(s),c.title||c.kicker)}</div></section>`}
function renderLocation(s,c){return `<section class="vc-section location template-${attr(s.template)} variant-${attr(s.variant||'map-split')}" data-role="${attr(s.role||'ORIENT')}" data-layout="${attr(s.layoutMode||'split')}" id="${attr(s.id)}"><div>${sectionHead(c.kicker,c.title)}<p class="lead">${esc(c.body||'')}</p><a class="button ghost" href="#contact">Get directions ${arrow}</a></div><div class="map-art">${img(media(s),'Location')}</div></section>`}
function renderFinal(v,s){const c=v.content.model.final||{};return `<section class="conversion-band template-${attr(s.template)}" data-role="${attr(s.role||'CONVERT')}" id="contact"><div><span class="kicker">${esc(c.eyebrow)}</span><h2>${esc(c.headline)}</h2></div><div class="conversion-actions"><a class="button primary" href="#top">${esc(c.primary)} ${arrow}</a><a class="button ghost" href="#top">${esc(c.secondary)}</a></div></section>`}


function renderHeroProduct(v,s,plan){const c=v.content.model.hero||{};const hero=media(s);const entities=(plan.product?.entities||[]).slice(0,4).map(x=>x.name);return `<section class="vc-hero hero-product-stage template-${attr(s.template)}" data-layout="${attr(s.layoutMode||'split')}" id="top"><div class="product-hero-grid"><div class="product-hero-copy"><span class="kicker">${esc(c.eyebrow)}</span><h1>${esc(c.headline)}</h1><p>${esc(c.subheadline)}</p><div class="actions"><a class="button primary" href="#contact">${esc(c.primary)} ${arrow}</a><a class="button ghost" href="#contact">${esc(c.secondary)}</a></div><div class="product-chips">${entities.map(x=>`<span>${esc(x)}</span>`).join('')}</div></div><div class="product-stage-frame"><div class="stage-toolbar"><i></i><i></i><i></i><span>${esc(domainDisplayName(plan.project.domainArchetype,plan.project.locale))}</span></div>${hero?img(hero,c.headline,'product-stage-image'):`<div class="stage-placeholder"><strong>${esc(v.content.brand)}</strong><span>PRODUCT EXPERIENCE</span></div>`}</div></div></section>`}
function renderHeroEditorial(v,s){const c=v.content.model.hero||{};const hero=media(s);return `<section class="vc-hero hero-editorial-center template-${attr(s.template)}" data-layout="${attr(s.layoutMode||'editorial')}" id="top"><div class="editorial-hero-media">${img(hero,c.headline,'editorial-hero-image')}</div><div class="editorial-hero-copy"><span class="kicker">${esc(c.eyebrow)}</span><h1>${esc(c.headline)}</h1><p>${esc(c.subheadline)}</p><div class="actions"><a class="button primary" href="#contact">${esc(c.primary)} ${arrow}</a><a class="text-link" href="#contact">${esc(c.secondary)} ${arrow}</a></div></div></section>`}
function renderHeroPublication(v,s,plan){const c=v.content.model.hero||{};const hero=media(s);const topics=(plan.designStrategy?.navigation_model?.items||[]).filter(x=>x.id!=='home').slice(0,4);return `<section class="vc-hero hero-publication-cover template-${attr(s.template)}" data-layout="${attr(s.layoutMode||'editorial')}" id="top"><div class="publication-masthead"><span>INDEPENDENT PUBLICATION</span><strong>${esc(v.content.brand)}</strong><small>LATEST EDITION</small></div><div class="publication-cover-grid"><div class="publication-lead"><span class="kicker">${esc(c.eyebrow)}</span><h1>${esc(c.headline)}</h1><p>${esc(c.subheadline)}</p><a class="text-link" href="#latest-content">Read the lead story ${arrow}</a></div><div class="publication-image">${img(hero,c.headline,'publication-cover-image')}</div><aside class="publication-index"><span>SECTIONS</span>${topics.map((x,i)=>`<a href="#${attr(x.id)}"><b>0${i+1}</b>${esc(x.label)}</a>`).join('')}<div class="publication-actions"><a class="button primary" href="#contact">${esc(c.primary)} ${arrow}</a></div></aside></div></section>`}
function renderHeroConversion(v,s){const c=v.content.model.hero||{};const next=v.content.model['next-event'];return `<section class="vc-hero hero-conversion-focus template-${attr(s.template)}" data-layout="${attr(s.layoutMode||'conversion')}" id="top"><div class="conversion-hero-copy"><span class="kicker">${esc(c.eyebrow)}</span><h1>${esc(c.headline)}</h1><p>${esc(c.subheadline)}</p><div class="actions"><a class="button primary" href="#contact">${esc(c.primary)} ${arrow}</a><a class="button ghost" href="#contact">${esc(c.secondary)}</a></div></div><aside class="conversion-proof"><span>DECISION READY</span><strong>${esc(next?.title||v.content.brand)}</strong><p>${esc(next?.location||'Clear proof, clear next step, minimal friction.')}</p><a href="#contact">${esc(c.primary)} ${arrow}</a></aside></section>`}
function renderServiceStack(s,c){const items=c.features||c.items||[];return `<section class="vc-section service-stack template-${attr(s.template)}" data-layout="${attr(s.layoutMode||'editorial')}" id="${attr(s.id)}">${sectionHead(c.kicker,c.title)}${c.body?`<p class="lead">${esc(c.body)}</p>`:''}<div class="service-stack-list">${items.map((x,i)=>{const a=Array.isArray(x)?x:[x.title||x.name,x.body||x.meta];return `<article><span>0${i+1}</span><h3>${esc(a[0])}</h3><p>${esc(a[1]||'')}</p><b>${arrow}</b></article>`}).join('')}</div></section>`}
function renderGalleryFilmstrip(s,c){return `<section class="vc-section gallery-filmstrip template-${attr(s.template)}" data-layout="${attr(s.layoutMode||'mosaic')}" id="${attr(s.id)}">${sectionHead(c.kicker,c.title,'View full gallery')}<div class="filmstrip">${(c.items||[]).map((x,i)=>`<figure class="film-${(i%3)+1}">${img(media(s,i),x.title||'Gallery image')}<figcaption><span>0${i+1}</span>${esc(x.title||'')}</figcaption></figure>`).join('')}</div></section>`}
function renderQuoteGrid(s,c){const items=c.items||[];return `<section class="vc-section quote-grid template-${attr(s.template)}" data-layout="${attr(s.layoutMode||'split')}" id="${attr(s.id)}">${sectionHead(c.kicker,c.title||'What people say')}<div class="quote-grid-items">${items.map((x,i)=>`<blockquote><span>“</span><p>${esc(x.body||x.quote||x.meta||'Trusted by people who needed the outcome to work.')}</p><footer><strong>${esc(x.title||x.name||`Client ${i+1}`)}</strong><small>${esc(x.meta||'')}</small></footer></blockquote>`).join('')}</div></section>`}
function renderPricingFeatured(s,c){const items=c.items||[];return `<section class="vc-section pricing-featured template-${attr(s.template)}" data-layout="${attr(s.layoutMode||'conversion')}" id="${attr(s.id)}">${sectionHead(c.kicker,c.title)}<div class="pricing-featured-grid">${items.map((x,i)=>`<article class="${i===1?'is-featured':''}"><span>${i===1?'RECOMMENDED':`0${i+1}`}</span><h3>${esc(x.title||x.name||'Plan')}</h3><strong>${esc(x.price||'Custom')}</strong><p>${esc(x.body||x.meta||'')}</p><a class="button ${i===1?'primary':'ghost'}" href="#contact">Choose plan ${arrow}</a></article>`).join('')}</div></section>`}
function renderArticleGrid(s,c){return `<section class="vc-section article-grid-section template-${attr(s.template)}" data-layout="${attr(s.layoutMode||'editorial')}" id="${attr(s.id)}">${sectionHead(c.kicker,c.title||'Latest')}<div class="article-grid">${(c.items||[]).map((x,i)=>`<article class="article-${i+1}">${media(s,i)?`<div class="article-media">${img(media(s,i),x.title||'Article')}</div>`:''}<span>${esc(x.meta||`0${i+1}`)}</span><h3>${esc(x.title||x.name||'Story')}</h3><p>${esc(x.body||'')}</p><a href="#contact">Read ${arrow}</a></article>`).join('')}</div></section>`}
function renderCtaSplit(v,s){const c=s.id==='final-cta'?(v.content.model.final||{}):(s.content||{});return `<section class="cta-split template-${attr(s.template)}" data-layout="${attr(s.layoutMode||'conversion')}" id="${s.id==='final-cta'?'contact':attr(s.id)}"><div><span class="kicker">${esc(c.eyebrow||c.kicker||'NEXT STEP')}</span><h2>${esc(c.headline||c.title||'Stay in the loop.')}</h2><p>${esc(c.body||'A focused next action without visual noise.')}</p></div><div class="cta-split-action"><a class="button primary" href="#top">${esc(c.primary||c.cta||'Continue')} ${arrow}</a><small>${esc(c.secondary||'No unnecessary friction.')}</small></div></section>`}


const DOMAIN_HERO_LABELS={
  'hero-academic-campus':['PROGRAMMES','ADMISSIONS','CAMPUS'],
  'hero-careers-search':['SEARCH ROLES','COMPANIES','CAREER ADVICE'],
  'hero-industrial-spec':['PRODUCTS','CAPABILITIES','REQUEST QUOTE'],
  'hero-finance-trust':['SERVICES','SECURITY','DOCUMENTS'],
  'hero-community-membership':['MEMBERSHIP','EVENTS','DIRECTORY'],
  'hero-restaurant-menu':['MENU','RESERVATIONS','PRIVATE DINING'],
  'hero-professional-authority':['PRACTICE AREAS','PROFESSIONALS','INSIGHTS'],
  'hero-commerce-catalog':['SHOP','COMPARE','DELIVERY'],
  'hero-corporate-manifesto':['CAPABILITIES','WORK','APPROACH']
};
function renderDomainHero(v,s,plan,renderer){
  const c=v.content.model.hero||{},hero=media(s),labels=domainHeroLabels(renderer,plan.project?.locale,DOMAIN_HERO_LABELS[renderer]||[]),nav=(plan.designStrategy?.navigation_model?.items||[]).filter(x=>x.id!=='home').slice(0,5);
  const extra=renderer==='hero-careers-search'?`<div class="domain-search-strip"><span>Role or keyword</span><span>Location</span><b>Search ${arrow}</b></div>`:renderer==='hero-industrial-spec'?`<div class="domain-spec-strip"><span>TECHNICAL EVALUATION</span><strong>SPEC → PROOF → RFQ</strong></div>`:renderer==='hero-finance-trust'?`<div class="domain-trust-strip"><span>VERIFIED STATUS</span><span>DOCUMENTED CONTROLS</span><span>NO RETURN PROMISES</span></div>`:'';
  return `<section class="domain-special-hero ${attr(renderer)} template-${attr(s.template)}" data-role="${attr(s.role||'OPEN')}" data-layout="${attr(s.layoutMode||'split')}" id="top"><div class="domain-hero-grid"><div class="domain-hero-copy"><span class="kicker">${esc(c.eyebrow)}</span><h1>${esc(c.headline)}</h1><p>${esc(c.subheadline)}</p><div class="actions"><a class="button primary" href="#contact">${esc(c.primary)} ${arrow}</a><a class="button ghost" href="#contact">${esc(c.secondary)}</a></div>${extra}</div><div class="domain-hero-visual">${img(hero,c.headline,'domain-hero-image')}<div class="domain-hero-index">${(labels.length?labels:nav.map(x=>x.label)).map((x,i)=>`<span><b>0${i+1}</b>${esc(x)}</span>`).join('')}</div></div></div></section>`;
}
function renderDomainCollection(s,c,renderer){
  const source=c.items||c.features||c.metrics||[];
  const items=source.map(x=>Array.isArray(x)?{title:x[0],body:x[1]}:x);
  return `<section class="vc-section domain-collection ${attr(renderer)} template-${attr(s.template)}" data-role="${attr(s.role||'VALUE')}" data-layout="${attr(s.layoutMode||'editorial')}" id="${attr(s.id)}">${sectionHead(c.kicker,c.title)}${c.body?`<p class="lead">${esc(c.body)}</p>`:''}<div class="domain-collection-grid">${items.map((x,i)=>`<article><span>0${i+1}</span><h3>${esc(x.title||x.name||'Item')}</h3>${x.price?`<strong>${esc(x.price)}</strong>`:''}<p>${esc(x.body||x.meta||'')}</p><b>${arrow}</b></article>`).join('')}</div></section>`;
}

function renderAdaptive(v,s,c,plan){
  const items=c.items||[];
  const entities=(plan.product?.entities||[]).slice(0,7).map(x=>x.name);
  const labels=items.length?items.map(x=>x.title||x.name).filter(Boolean):entities;
  return `<section class="vc-section adaptive-section project-local" data-role="${attr(s.role||'VALUE')}" data-layout="${attr(s.layoutMode||'immersive')}" id="${attr(s.id)}"><div class="adaptive-orbit" aria-hidden="true"><i></i><i></i><i></i></div><div class="adaptive-copy">${sectionHead(c.kicker||'DOMAIN SIGNATURE',c.title||'A composition made for this idea.')}<p class="lead">${esc(c.body||'Project-local composition synthesized because the registry had no sufficient semantic match.')}</p><div class="entity-cloud">${labels.map((x,i)=>`<span style="--i:${i}">${esc(x)}</span>`).join('')}</div><small class="provisional-note">PROJECT-LOCAL · DESIGN REVIEW REQUIRED</small></div></section>`;
}

export function renderSection(v,s,plan){
  const c=s.content||{};const renderer=s.rendererKey||s.template||'';
  if(plan?.project?.domainArchetype==='florist-retail'&&s.id==='hero')return renderHeroEditorial(v,s);
  if(renderer==='adaptive-section')return renderAdaptive(v,s,c,plan);
  if(renderer==='hero-product-stage')return renderHeroProduct(v,s,plan);
  if(renderer==='hero-editorial-center')return renderHeroEditorial(v,s);
  if(renderer==='hero-publication-cover')return renderHeroPublication(v,s,plan);
  if(renderer==='hero-conversion-focus')return renderHeroConversion(v,s);
  if(DOMAIN_HERO_LABELS[renderer])return renderDomainHero(v,s,plan,renderer);
  if(['programme-grid','vacancy-grid','capability-matrix','finance-trust-ledger','membership-grid','menu-grid','practice-index','product-catalog-grid','capability-index'].includes(renderer))return renderDomainCollection(s,c,renderer);
  if(renderer==='service-stack')return renderServiceStack(s,c);
  if(renderer==='gallery-filmstrip')return renderGalleryFilmstrip(s,c);
  if(renderer==='quote-grid')return renderQuoteGrid(s,c);
  if(renderer==='pricing-featured')return renderPricingFeatured(s,c);
  if(renderer==='article-grid')return renderArticleGrid(s,c);
  if(renderer==='cta-split')return renderCtaSplit(v,s);
  if(s.id==='hero')return renderHero(v,s,plan);
  if(s.id==='final-cta')return renderFinal(v,s);
  if(s.id==='next-event')return renderNextEvent(s,c);
  if(s.id==='latest-content'&&c.items)return renderEvents(s,c);
  if(['artists','team'].includes(s.id))return renderPeople(s,c);
  if(s.id==='gallery')return renderGallery(s,c);
  if(['experience'].includes(s.id)||renderer.includes('feature-media'))return renderFeatures(s,c);
  if(['proof','outcomes','security','trust-strip'].includes(s.id)&&c.metrics)return renderMetrics(s,c);
  if(['process','workflow','how-it-works','schedule'].includes(s.id))return renderSteps(s,c);
  if(s.id==='faq')return renderFaq(s,c);
  if(s.id==='location')return renderLocation(s,c);
  if(['statement','about','case-study','product-proof','task-preview'].includes(s.id))return renderEditorial(s,c);
  return renderCards(s,c);
}


function pageDepth(currentPath='/'){return currentPath==='/'?0:currentPath.split('/').filter(Boolean).length}
function routeHref(targetPath='/',currentPath='/'){const prefix=pageDepth(currentPath)?'../'.repeat(pageDepth(currentPath)):'./';if(targetPath==='/')return prefix;return prefix+targetPath.replace(/^\/|\/$/g,'')+'/'}
function navigation(plan,currentPath='/'){
  const strategyItems=plan.designStrategy?.navigation_model?.items||[];
  if(strategyItems.length) return strategyItems.slice(0,plan.designStrategy.navigation_model.maxPrimary||8).map(item=>`<a href="${attr(routeHref(item.path,currentPath))}">${esc(item.label)}</a>`).join('');
  const pages=(plan.siteBlueprint?.pages||[]).filter(x=>!x.dynamic).slice(0,7);
  return pages.map(p=>`<a href="${attr(routeHref(p.path,currentPath))}">${esc(p.title)}</a>`).join('');
}
function localeText(plan){const cs=plan.project.locale?.language==='cs';return cs?{rights:'Všechna práva vyhrazena.',location:'MÍSTO',newsletter:'NOVINKY',email:'Váš e-mail',subscribe:'Přihlásit',privacy:'Soukromí',terms:'Podmínky',menu:'Otevřít menu'}:{rights:'All rights reserved.',location:'LOCATION',newsletter:'NEWSLETTER',email:'Your email',subscribe:'Subscribe',privacy:'Privacy',terms:'Terms',menu:'Open menu'};}
function footerHtml(plan,visual,currentPath='/'){const footer=visual.content.model.footer||{},t=localeText(plan);return `<footer class="site-footer"><div><strong>${esc(plan.brand.identity.name)}</strong><small>© ${new Date().getUTCFullYear()} ${esc(t.rights)}</small></div><div><span>${esc(t.location)}</span><p>${esc(footer.location||'')}</p></div><div><span>${esc(t.newsletter)}</span><p>${esc(footer.newsletter||'')}</p><form><label class="sr-only" for="email">${esc(uiText(plan.project.locale).emailLabel)}</label><input id="email" type="email" placeholder="${esc(t.email)}"><button type="button" aria-label="${esc(t.subscribe)}">${arrow}</button></form></div><div class="footer-links"><a href="${attr(routeHref('/',currentPath))}">${esc(t.privacy)}</a><a href="${attr(routeHref('/',currentPath))}">${esc(t.terms)}</a></div></footer>`}
function interactionScript(){return `<script>(()=>{for(const root of document.querySelectorAll('[data-wf-form-root]')){const form=root.querySelector('form');if(!form)continue;const syncInvalid=()=>{for(const field of form.querySelectorAll('input,textarea,select'))field.toggleAttribute('aria-invalid',!field.checkValidity())};form.addEventListener('submit',e=>{e.preventDefault();const ok=form.checkValidity();root.dataset.uiState=ok?'success':'error';syncInvalid();if(!ok)form.querySelector(':invalid')?.focus()});form.addEventListener('input',()=>{root.dataset.uiState='empty';for(const field of form.querySelectorAll('[aria-invalid]'))field.removeAttribute('aria-invalid')})}})()</script>`}
function shell(plan,visual,body,{currentPath='/',title=plan.brand.content.seo.title,description=plan.brand.content.seo.description}={}){
  const depth=pageDepth(currentPath),prefix=depth?'../'.repeat(depth):'./';
  const t=localeText(plan),lang=plan.project.locale?.tag||'en';
  const html=`<!doctype html><html lang="${attr(lang)}" data-domain="${attr(plan.project.domainArchetype||'')}" data-template="${attr(plan.layout.id)}" data-brand="${attr(plan.brand.identity.name)}" data-mood="${attr(plan.brand.style.mood)}" data-art-direction="${attr(visual.artDirection.theme.id)}" data-canvas="${attr(visual.spatial?.canvas||'framed')}" data-strategy="${attr(plan.designStrategy?.layout_strategy?.primary||'narrative-balanced')}" data-hero-strategy="${attr(plan.designStrategy?.layout_strategy?.hero||'value-led')}" data-nav-model="${attr(plan.designStrategy?.navigation_model?.pattern||plan.layout.nav||'standard')}" data-density="${attr(plan.designStrategy?.visual_density||plan.designDNA?.density||'balanced')}" data-color-temperature="${attr(plan.designStrategy?.color_strategy?.temperature||'neutral')}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="${attr(description)}"><title>${esc(title)}</title><link rel="stylesheet" href="${prefix}styles.css"></head><body><header class="site-header"><a class="brand" href="${attr(routeHref('/',currentPath))}">${esc(plan.brand.identity.name)}</a><nav>${navigation(plan,currentPath)}</nav><a class="header-cta" href="${attr(routeHref('/contact/',currentPath))}">${esc(visual.content.model.hero?.primary||plan.brand.content.primaryCta)}</a><button class="menu-button" aria-label="${esc(t.menu)}">${plan.project.locale?.language==='cs'?'Menu':'Menu'}</button></header>${body}${footerHtml(plan,visual,currentPath)}${interactionScript()}</body></html>`;
  const localized=localizeRenderedHtml(html,plan.project.locale);
  return depth?localized.replaceAll('src="assets/','src="'+prefix+'assets/'):localized;
}
export function renderWebsite(plan,visual,projectId){
  const byId=Object.fromEntries(visual.sections.map(s=>[s.id,s]));
  const sections=(visual.zones||visual.sections.map(s=>({id:s.id,kind:'single',members:[s.id]}))).map(z=>{const inner=z.members.map(id=>byId[id]?applySpatial(renderSection(visual,byId[id],plan),byId[id]):'').join('');return z.kind==='single'?inner:`<div class="composition-zone zone-${attr(z.kind)} zone-${attr(z.id)}" data-zone="${attr(z.id)}" data-zone-kind="${attr(z.kind)}">${inner}</div>`}).join('');
  return shell(plan,visual,`<main data-narrative="${attr(plan.layout.direction?.narrative||'')}">${sections}</main>`,{currentPath:'/'});
}
function detailContract(kind='product',locale=null){
  const localized=detailCopy(kind,locale);if(localized)return localized;
  const contracts={
    product:{label:'Product / evaluate',facts:['Price requires approved source data','Availability requires a live source','Terms and fulfilment must be verified'],action:'Choose the next product step'},
    property:{label:'Property / inspect',facts:['Price and status require listing data','Address and availability must be verified','Viewing terms require a live source'],action:'Request a verified viewing'},
    job:{label:'Role / evaluate',facts:['Compensation requires employer data','Location and work mode must be verified','Closing date requires a live source'],action:'Review the application path'},
    course:{label:'Course / decide',facts:['Dates and timetable require programme data','Fees require an approved source','Admissions requirements must be verified'],action:'Review admissions'},
    article:{label:'Article / read',facts:['Author attribution requires source data','Publication date must be verified','Related content comes from the content source'],action:'Continue through the topic'},
    event:{label:'Event / attend',facts:['Date and time require event data','Venue details must be verified','Tickets and availability require a live source'],action:'Check event availability'},
    profile:{label:'Profile / understand',facts:['Role and biography require profile data','Credentials require verified source data','Availability or contact rules require a live source'],action:'Continue to the appropriate contact path'}
  };return contracts[kind]||contracts.product;
}
function renderDetailIntro(plan,page){
  const kind=page.detailKind||'product', spec=detailContract(kind,plan.project?.locale), t=uiText(plan.project?.locale);
  const facts=spec.facts.map((x,i)=>`<li><span>0${i+1}</span>${rawEsc(x)}</li>`).join('');
  return `<section class="detail-intro detail-${attr(kind)}" data-detail-kind="${attr(kind)}"><div class="detail-heading"><span class="kicker">${esc(spec.label)}</span><h1>${esc(page.title)}</h1><p>${esc(page.purpose||'Evaluate the detail and continue with verified information.')}</p></div><aside class="detail-facts"><strong>${esc(t.truthBoundary)}</strong><ul>${facts}</ul><a class="button primary" href="#detail-action">${esc(spec.action)}</a></aside></section>`;
}
function renderPageState(plan,page){
  const family=page.family||'overview',t=uiText(plan.project?.locale);
  if(family==='action'||family==='contact') return `<section class="wf-state-panel wf-form-panel" data-wf-state-root data-wf-form-root data-ui-state="empty"><div class="wf-state-copy"><span class="kicker">${esc(t.formContract)}</span><h2>${esc(t.formHeadline)}</h2><div class="wf-state-feedback" aria-live="polite"><p class="wf-state-view" data-state="empty">${esc(t.formEmpty)}</p><p class="wf-state-view" data-state="error">${esc(t.formError)}</p><p class="wf-state-view" data-state="success">${esc(t.formSuccess)}</p></div></div><form class="wf-action-form" novalidate><label for="wf-name-${attr(page.id)}">${esc(t.name)}</label><input id="wf-name-${attr(page.id)}" name="name" autocomplete="name" required><label for="wf-email-${attr(page.id)}">${esc(t.emailLabel)}</label><input id="wf-email-${attr(page.id)}" name="email" type="email" autocomplete="email" required><label for="wf-message-${attr(page.id)}">${esc(t.details)}</label><textarea id="wf-message-${attr(page.id)}" name="details" rows="5" required></textarea><button class="button primary" type="submit">${esc(t.continue)}</button></form></section>`;
  if(family==='listing') return `<section class="wf-state-panel wf-collection-state" data-wf-state-root data-ui-state="ready"><div><span class="kicker">${esc(t.collectionContract)}</span><h2>${esc(t.collectionHeadline)}</h2></div><div class="wf-state-feedback" aria-live="polite"><p class="wf-state-view" data-state="ready">${esc(t.resultsReady)}</p><p class="wf-state-view" data-state="empty">${esc(t.resultsEmpty)}</p><p class="wf-state-view" data-state="error">${esc(t.resultsError)}</p></div></section>`;
  return '';
}
function renderPageIntro(plan,page){
  const family=page.family||'overview', purpose=page.purpose||plan.brand.content.seo.description;
  if(family==='detail') return renderDetailIntro(plan,page);
  const labels={listing:'Browse / compare',detail:'Detail / decide',pricing:'Plans / decision',contact:'Contact / next step',about:'Story / people',action:'Action / completion',editorial:'Read / explore',evidence:'Evidence / trust',application:'Workspace / task',overview:'Overview'};
  const localized=pageFamilyCopy(family,plan.project?.locale),familyLabel=localized?.label||labels[family]||labels.overview;
  const base=`<div class="page-intro-copy"><span class="kicker">${esc(familyLabel)}</span><h1>${esc(page.title)}</h1><p>${esc(purpose)}</p></div>`;
  if(family==='listing') return `<section class="page-intro page-intro-listing">${base}<aside class="page-intro-aside"><span>${esc(localized?.asideLabel||'EXPLORE')}</span><strong>${esc(localized?.asideTitle||page.title)}</strong><p>${esc(localized?.asideBody||'Scan, compare and move into the relevant detail path.')}</p></aside></section>`;
  if(family==='editorial') return `<section class="page-intro page-intro-editorial">${base}<aside class="page-intro-aside"><span>${esc(localized?.asideLabel||'EDITORIAL')}</span><strong>${esc(localized?.asideTitle||'Current thinking')}</strong><p>${esc(localized?.asideBody||'Organized for reading, discovery and return visits.')}</p></aside></section>`;
  if(family==='pricing') return `<section class="page-intro page-intro-pricing">${base}<aside class="page-intro-aside"><span>${esc(localized?.asideLabel||'DECISION')}</span><strong>${esc(localized?.asideTitle||'Compare by fit')}</strong><p>${esc(localized?.asideBody||'Terms and prices require approved source data.')}</p></aside></section>`;
  if(family==='action'||family==='contact') return `<section class="page-intro page-intro-action">${base}<aside class="page-intro-aside"><span>${esc(localized?.asideLabel||'NEXT STEP')}</span><strong>${esc(localized?.asideTitle||(family==='contact'?'Start a conversation':'Complete one clear action'))}</strong><p>${esc(localized?.asideBody||'Required details stay explicit and minimal.')}</p></aside></section>`;
  if(family==='about') return `<section class="page-intro page-intro-about">${base}</section>`;
  if(family==='evidence') return `<section class="page-intro page-intro-evidence">${base}<aside class="page-intro-aside"><span>${esc(localized?.asideLabel||'PROOF')}</span><strong>${esc(localized?.asideTitle||'Evidence before promise')}</strong><p>${esc(localized?.asideBody||'Only verified claims belong in this path.')}</p></aside></section>`;
  if(family==='application') return `<section class="page-intro page-intro-application">${base}<aside class="page-intro-aside"><span>${esc(localized?.asideLabel||'TASK')}</span><strong>${esc(localized?.asideTitle||'Get to the job quickly')}</strong><p>${esc(localized?.asideBody||'Interface structure follows the repeated user task.')}</p></aside></section>`;
  return `<section class="page-intro page-intro-overview">${base}</section>`;
}
export function renderBlueprintPage(plan,visual,page){
  const byId=Object.fromEntries(visual.sections.map(s=>[s.id,s]));
  const picked=page.sectionHints.filter(id=>!['hero','final-cta'].includes(id)&&byId[id]).slice(0,5);
  const sections=picked.map(id=>renderSection(visual,byId[id],plan)).join('');
  const final=byId['final-cta']?renderSection(visual,byId['final-cta'],plan):'';
  const intro=renderPageIntro(plan,page), state=renderPageState(plan,page);
  return shell(plan,visual,`<main class="subpage" data-page="${attr(page.id)}" data-family="${attr(page.family||'overview')}" data-detail-kind="${attr(page.detailKind||'')}">${intro}${state}${sections}${final}</main>`,{currentPath:page.path,title:`${page.title} — ${plan.brand.identity.name}`});
}

